const CREDITEX_REQUIRED_CASE_COLUMNS = [
  "commercial_handoff_id",
  "accepted_quote_version_id",
  "accepted_scope_sha256",
] as const;

type SchemaGuardDefinition = {
  readonly name: string;
  readonly sql: string;
};

export function canonicalCreditexSchemaGuardSql(sql: string) {
  const normalisedPrefix = sql
    .trim()
    .replace(
      /^CREATE\s+TRIGGER\s+(?:IF\s+NOT\s+EXISTS\s+)?/i,
      "CREATE TRIGGER ",
    )
    .replace(/;\s*$/, "");
  let canonical = "";
  let quote = "";
  let pendingWhitespace = false;
  for (let index = 0; index < normalisedPrefix.length; index += 1) {
    const character = normalisedPrefix[index];
    if (quote) {
      canonical += character;
      if (character !== quote) continue;
      if (
        quote === "'"
        && normalisedPrefix[index + 1] === "'"
      ) {
        canonical += normalisedPrefix[index + 1];
        index += 1;
      } else {
        quote = "";
      }
      continue;
    }
    if (character === "'" || character === "\"" || character === "`") {
      if (pendingWhitespace && canonical) canonical += " ";
      pendingWhitespace = false;
      quote = character;
      canonical += character;
      continue;
    }
    if (/\s/.test(character)) {
      pendingWhitespace = true;
      continue;
    }
    if (pendingWhitespace && canonical) canonical += " ";
    pendingWhitespace = false;
    canonical += character;
  }
  return canonical.trim();
}

async function installedGuards(database: D1Database) {
  const installed = new Map<string, string>();
  const result = await database.prepare(
    `SELECT name, sql FROM sqlite_schema WHERE type = 'trigger'`,
  ).all<{ name: string; sql: string | null }>();
  for (const row of result.results) {
    installed.set(String(row.name), String(row.sql || ""));
  }
  return installed;
}

async function requireCreditexSchemaMigrations(database: D1Database) {
  const tableNames = CREDITEX_REQUIRED_SCHEMA_TABLES
    .map((name) => `'${name}'`)
    .join(", ");
  const tables = await database.prepare(
    `SELECT name FROM sqlite_schema
      WHERE type = 'table'
        AND name IN (${tableNames})`,
  ).all<{ name: string }>();
  const caseColumns = await database.prepare(
    "PRAGMA table_xinfo(`compliance_cases`)",
  ).all<{ name: string }>();
  const installedTables = new Set(
    tables.results.map((row) => String(row.name)),
  );
  const installedCaseColumns = new Set(
    caseColumns.results.map((row) => String(row.name)),
  );
  const missing = [
    ...CREDITEX_REQUIRED_SCHEMA_TABLES
      .filter((name) => !installedTables.has(name))
      .map((name) => `table:${name}`),
    ...CREDITEX_REQUIRED_CASE_COLUMNS
      .filter((name) => !installedCaseColumns.has(name))
      .map((name) => `column:compliance_cases.${name}`),
  ];
  if (missing.length) {
    throw new Error(`CREDITEX_SCHEMA_MIGRATIONS_REQUIRED:${missing.join(",")}`);
  }
}

async function installCreditexSchemaGuards(
  database: D1Database,
  definitions: readonly SchemaGuardDefinition[],
) {
  await requireCreditexSchemaMigrations(database);
  const installed = await installedGuards(database);
  const mismatched = definitions.filter(
    (definition) =>
      installed.has(definition.name) &&
      canonicalCreditexSchemaGuardSql(installed.get(definition.name) || "")
        !== canonicalCreditexSchemaGuardSql(definition.sql),
  );
  if (mismatched.length) {
    throw new Error(
      `CREDITEX_SCHEMA_GUARD_MISMATCH:${mismatched
        .map((definition) => definition.name)
        .join(",")}`,
    );
  }
  const missing = definitions.filter(
    (definition) => !installed.has(definition.name),
  );
  if (
    missing.some((definition) =>
      CREDITEX_CALCULATOR_AUTHORING_SCHEMA_GUARD_NAMES.has(definition.name)
    )
  ) {
    const preseeded = await database.prepare(`SELECT
        (
          SELECT COUNT(*)
          FROM compliance_calculator_authoring_receipts
        )
        + (
          SELECT COUNT(*)
          FROM compliance_calculator_vector_authoring_receipts
        ) row_count`)
      .first<{ row_count: number }>();
    if (Number(preseeded?.row_count || 0) > 0) {
      throw new Error(
        "CREDITEX_CALCULATOR_AUTHORING_PRESEED_ROWS_BLOCKED",
      );
    }
  }
  const batch = missing.slice(0, SCHEMA_INSTALL_BATCH_SIZE);
  if (batch.length) {
    await database.batch(
      batch.map((definition) => database.prepare(definition.sql)),
    );
  }
  const verified = await installedGuards(database);
  const unavailable = batch.filter(
    (definition) =>
      canonicalCreditexSchemaGuardSql(verified.get(definition.name) || "")
        !== canonicalCreditexSchemaGuardSql(definition.sql),
  );
  if (unavailable.length) {
    throw new Error(
      `CREDITEX_SCHEMA_GUARDS_UNAVAILABLE:${unavailable
        .map((definition) => definition.name)
        .join(",")}`,
    );
  }
  const remaining = definitions.filter(
    (definition) => !verified.has(definition.name),
  );
  if (remaining.length) {
    throw new Error(`CREDITEX_SCHEMA_GUARDS_INSTALLING:${remaining.length}`);
  }
}

export async function ensureCreditexSchemaGuards(database: D1Database) {
  const databaseKey = database as object;
  let readiness = readinessByDatabase.get(databaseKey);
  if (!readiness) {
    readiness = installCreditexSchemaGuards(
      database,
      CREDITEX_SCHEMA_GUARD_DEFINITIONS,
    );
    readinessByDatabase.set(databaseKey, readiness);
  }
  try {
    await readiness;
  } catch (error) {
    readinessByDatabase.delete(databaseKey);
    throw error;
  }
}

export async function ensureCreditexPilotSchemaGuards(
  database: D1Database,
) {
  const databaseKey = database as object;
  let readiness = pilotReadinessByDatabase.get(databaseKey);
  if (!readiness) {
    readiness = installCreditexSchemaGuards(
      database,
      CREDITEX_PILOT_SCHEMA_GUARD_DEFINITIONS,
    );
    pilotReadinessByDatabase.set(databaseKey, readiness);
  }
  try {
    await readiness;
  } catch (error) {
    pilotReadinessByDatabase.delete(databaseKey);
    throw error;
  }
}
